async (page) => {
  const errs = [];
  page.on('console', m => { if (m.type() === 'error') errs.push(m.text()); });
  page.on('pageerror', e => errs.push('pageerror: ' + e.message));
  const sel = page.locator('select');
  await sel.nth(0).selectOption('123');
  await sel.nth(1).selectOption('1');
  const dispatch = page.waitForResponse(r => r.url().includes('/dispatch'));
  await page.getByRole('button', { name: 'Request Ride' }).click();
  const r = await dispatch;
  await page.waitForTimeout(8000);
  const text = await page.locator('body').innerText();
  await page.screenshot({ path: '/tmp/hr/ui.png' });
  return { status: r.status(), errs, text: text.slice(0, 1500), len: (await page.content()).length };
}

